        $h='<section class="admin-head"><div><span class="eyebrow">SEMANTIC PUBLISHING</span><h1>Articles</h1><p class="muted">Human-reviewed, crawlable NewsArticle pages built from newsroom copy or OCR source pages. Raw OCR is never auto-indexed.</p></div><div class="page-head-actions"><a class="btn ghost" href="/trust">View Trust Center</a><a class="btn ghost" href="/news-sitemap.xml" target="_blank" rel="noopener">News sitemap</a></div></section>'.(!empty($_GET['created'])?'<div class="alert success">Article draft created.</div>':'').(!empty($_GET['published'])?'<div class="alert success">Article published and discovery caches queued for refresh.</div>':'').'<div class="semantic-admin-grid"><section class="panel"><div class="section-head"><div><h2>Newsroom articles</h2><p class="muted">Draft → editorial review → publish. Unpublishing removes the article from public discovery without deleting history.</p></div><span class="pill">'.count($rows).'</span></div><div class="table-wrap"><table><thead><tr><th>Article</th><th>Source</th><th>Status</th><th>Published</th><th>Actions</th></tr></thead><tbody>';
