        $h.='</tbody></table></div></section>'.$this->articleEditor($edit,$pubs,$cities,$langs,$sections,$authors,$topics,$entities,$ocrPages,$editAuthors,$editTopics,$editEntities).'</div>';View::layout('Articles',$h,['brand'=>$this->brandName(),'admin'=>true]);
