        $assetDefs=[
            'logo'=>['setting'=>'brand.logo_path','label'=>'Primary logo','hint'=>'Header, Reader and clipping branding · PNG/JPEG/WebP · up to 8 MB'],
            'logo_dark'=>['setting'=>'brand.logo_dark_path','label'=>'Dark-mode logo','hint'=>'Optional alternate logo for dark Publisher/Reader surfaces'],
            'mark'=>['setting'=>'brand.mark_path','label'=>'Square brand mark','hint'=>'Recommended square artwork. Also generates favicon and app icon derivatives.'],
            'favicon'=>['setting'=>'brand.favicon_path','label'=>'Favicon','hint'=>'Square PNG/JPEG/WebP. A 64×64 PNG derivative is generated automatically.'],
        ];
        if($method==='POST'){
            $action=(string)($_POST['brand_action']??$_GET['brand_action']??'save');
            if($action==='remove_asset'){
                $slot=(string)($_POST['slot']??'');if(!isset($assetDefs[$slot]))$this->adminError('Unknown brand asset');$this->removeBrandAsset($slot,$assetDefs[$slot]['setting'],$userGuid);Audit::log('brand.asset.removed','settings',$slot,'SUCCESS');Http::redirect('/admin/settings/brand?asset_removed=1');
            }
            $siteName=trim((string)$this->postedSetting('brand.site_name',TenantData::setting('brand.site_name',$this->brandName()),$sitePresent));$tagline=trim((string)$this->postedSetting('brand.tagline',TenantData::setting('brand.tagline','Digital newspaper'),$taglinePresent));$accent=trim((string)$this->postedSetting('brand.accent',TenantData::setting('brand.accent','#2563eb'),$accentPresent));$footer=trim((string)$this->postedSetting('brand.footer_text',TenantData::setting('brand.footer_text',''),$footerPresent));
            if($siteName==='')$this->adminError('Site name is required');if(!preg_match('/^#[0-9a-f]{6}$/i',$accent))$this->adminError('Accent color must be a 6-digit hex color such as #2563eb');
            TenantData::setSetting('brand.site_name',$siteName,$userGuid);TenantData::setSetting('brand.tagline',$tagline,$userGuid);TenantData::setSetting('brand.accent',$accent,$userGuid);TenantData::setSetting('brand.footer_text',$footer,$userGuid);
            foreach($assetDefs as$slot=>$def){if(empty($_FILES[$slot])||($_FILES[$slot]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$url=$this->storeBrandAsset($slot,$_FILES[$slot]);TenantData::setSetting($def['setting'],$url,$userGuid);if($slot==='mark'){$base='/uploads/branding/'.RequestContext::tenantGuid();TenantData::setSetting('brand.apple_touch_icon_path',$base.'/apple-touch-icon.png?v='.time(),$userGuid);TenantData::setSetting('brand.pwa_icon_192_path',$base.'/pwa-192.png?v='.time(),$userGuid);TenantData::setSetting('brand.pwa_icon_512_path',$base.'/pwa-512.png?v='.time(),$userGuid);if(trim((string)TenantData::setting('brand.favicon_path',''))==='')TenantData::setSetting('brand.favicon_path',$base.'/favicon-32.png?v='.time(),$userGuid);}}
            Audit::log('brand.settings.updated','settings',RequestContext::tenantGuid(),'SUCCESS',['assets'=>array_keys(array_filter($_FILES,fn($f)=>is_array($f)&&($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK))]);Http::redirect('/admin/settings/brand?saved=1');
        }
        $tabs='';foreach(SettingsCatalog::groups() as$key=>$g)$tabs.='<a class="settings-tab '.($key==='brand'?'active':'').'" href="/admin/settings/'.$this->e($key).'">'.$this->e($g['label']).'</a>';
        $siteName=(string)TenantData::setting('brand.site_name',$this->brandName());$tagline=(string)TenantData::setting('brand.tagline','Digital newspaper');$accent=(string)TenantData::setting('brand.accent','#2563eb');$footer=(string)TenantData::setting('brand.footer_text','');
        $h='<section class="admin-head"><div><span class="eyebrow">PUBLISHER CONTROL</span><h1>Brand & identity</h1><p class="muted">Upload publisher assets directly. ePaper SaaS validates, optimizes and stores them per tenant—no file URL knowledge required.</p></div></section><nav class="settings-tabs">'.$tabs.'</nav>'.(!empty($_GET['saved'])?'<div class="alert success">Brand settings and assets updated.</div>':'').(!empty($_GET['asset_removed'])?'<div class="alert success">Brand asset removed.</div>':'').'<form method="post" enctype="multipart/form-data" class="brand-settings-stack">'.$this->csrf().'<section class="panel"><div class="section-head"><div><span class="eyebrow">IDENTITY</span><h2>Publisher identity</h2></div></div><div class="form-grid"><label>Site name<input name="settings[brand.site_name]" value="'.$this->e($siteName).'" required maxlength="120"></label><label>Tagline<input name="settings[brand.tagline]" value="'.$this->e($tagline).'" maxlength="180"></label><label>Accent color<div class="color-field"><input type="color" data-brand-color value="'.$this->e($accent).'"><input name="settings[brand.accent]" data-brand-color-text value="'.$this->e($accent).'" pattern="#[0-9A-Fa-f]{6}" required></div></label><label>Footer text<input name="settings[brand.footer_text]" value="'.$this->e($footer).'" maxlength="220"></label></div></section><section class="panel"><div class="section-head"><div><span class="eyebrow">ASSETS</span><h2>Logo & app assets</h2><p class="muted">Replace assets simply by selecting a new file and saving. Existing public URLs are managed automatically.</p></div></div><div class="brand-asset-grid">';
        foreach($assetDefs as$slot=>$def){$current=trim((string)TenantData::setting($def['setting'],''));$h.='<article class="brand-asset-card"><div class="brand-asset-preview '.($current?'has-image':'is-empty').'">'.($current?'<img src="'.$this->e($current).'" alt="'.$this->e($def['label']).' preview">':'<span>No asset uploaded</span>').'</div><div class="brand-asset-copy"><strong>'.$this->e($def['label']).'</strong><p>'.$this->e($def['hint']).'</p></div><label class="brand-upload-button">Choose file<input type="file" name="'.$this->e($slot).'" accept="image/png,image/jpeg,image/webp" data-brand-file></label>'.($current?'<button class="text-btn danger" type="submit" name="slot" value="'.$this->e($slot).'" formaction="/admin/settings/brand?brand_action=remove_asset" formnovalidate data-brand-remove data-slot="'.$this->e($slot).'">Remove</button>':'').($current?'<small class="asset-path">Managed asset</small>':'').'</article>';}
        $h.='</div><div class="brand-derivative-note"><strong>Automatic derivatives</strong><span>Uploading a square brand mark generates favicon-32, Apple Touch 180, PWA 192 and PWA 512 assets. SVG is intentionally not accepted to avoid unsafe embedded content.</span></div></section><div class="sticky-form-actions"><button class="btn primary" name="brand_action" value="save">Save brand & assets</button><span class="muted">PNG, JPEG or WebP · maximum 8 MB per file</span></div></form>';
        View::layout('Brand & identity',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }

    private function brandAssetDirectory(): string
    {
        $tenant=preg_replace('/[^0-9a-f-]/i','',RequestContext::tenantGuid());$dir=dirname(__DIR__,2).'/public_html/uploads/branding/'.$tenant;if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))$this->adminError('Could not create the tenant branding directory');return$dir;
    }

    private function storeBrandAsset(string $slot,array $file): string
    {
        $err=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($err!==UPLOAD_ERR_OK)$this->adminError('Brand asset upload failed (upload error '.$err.')');$size=(int)($file['size']??0);if($size<1||$size>8*1024*1024)$this->adminError('Brand assets must be smaller than 8 MB');$tmp=(string)($file['tmp_name']??'');if(!is_uploaded_file($tmp)&&!is_file($tmp))$this->adminError('Uploaded brand asset is unavailable');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($allowed[$mime]))$this->adminError('Use a PNG, JPEG or WebP image');$info=@getimagesize($tmp);if(!$info||($info[0]??0)<16||($info[1]??0)<16||($info[0]??0)>8000||($info[1]??0)>8000)$this->adminError('Brand image dimensions are invalid or too large');$dir=$this->brandAssetDirectory();$stamp=time();
        if(class_exists('Imagick')){try{$im=new \Imagick($tmp);if(method_exists($im,'autoOrient'))$im->autoOrient();$im->setImageColorspace(\Imagick::COLORSPACE_SRGB);$im->stripImage();if(in_array($slot,['logo','logo_dark'],true)){$im->thumbnailImage(1600,420,true,true);$im->setImageFormat('webp');$im->setImageCompressionQuality(91);$name=$slot==='logo'?'logo.webp':'logo-dark.webp';$target=$dir.'/'.$name;$temp=$target.'.tmp';$im->writeImage($temp);@rename($temp,$target);$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/'.$name.'?v='.$stamp;}if($slot==='mark'){$canvas=$this->squareBrandCanvas($im,512);$target=$dir.'/mark.webp';$canvas->setImageFormat('webp');$canvas->setImageCompressionQuality(91);$canvas->writeImage($target);$this->writeSquarePng($canvas,$dir.'/favicon-32.png',32);$this->writeSquarePng($canvas,$dir.'/apple-touch-icon.png',180);$this->writeSquarePng($canvas,$dir.'/pwa-192.png',192);$this->writeSquarePng($canvas,$dir.'/pwa-512.png',512);$canvas->clear();$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/mark.webp?v='.$stamp;}if($slot==='favicon'){$canvas=$this->squareBrandCanvas($im,128);$this->writeSquarePng($canvas,$dir.'/favicon.png',64);$canvas->clear();$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/favicon.png?v='.$stamp;}}catch(\Throwable $e){$this->adminError('Could not optimize brand asset: '.$e->getMessage());}}
        $ext=$allowed[$mime];$name=match($slot){'logo'=>'logo.'.$ext,'logo_dark'=>'logo-dark.'.$ext,'mark'=>'mark.'.$ext,'favicon'=>'favicon.'.$ext,default=>$slot.'.'.$ext};$target=$dir.'/'.$name;if(!@copy($tmp,$target))$this->adminError('Could not store the uploaded brand asset');return'/uploads/branding/'.RequestContext::tenantGuid().'/'.$name.'?v='.$stamp;
    }

    private function squareBrandCanvas(\Imagick $source,int $size): \Imagick
    {
        $src=clone$source;$src->setImageBackgroundColor(new \ImagickPixel('transparent'));$src->thumbnailImage($size,$size,true,true);$canvas=new \Imagick();$canvas->newImage($size,$size,new \ImagickPixel('transparent'),'png');$x=(int)(($size-$src->getImageWidth())/2);$y=(int)(($size-$src->getImageHeight())/2);$canvas->compositeImage($src,\Imagick::COMPOSITE_OVER,$x,$y);$src->clear();return$canvas;
    }

    private function writeSquarePng(\Imagick $source,string $target,int $size): void
    {
        $im=clone$source;$im->resizeImage($size,$size,\Imagick::FILTER_LANCZOS,1);$im->setImageFormat('png');$im->stripImage();$im->writeImage($target);$im->clear();
    }

    private function removeBrandAsset(string $slot,string $setting,?string $userGuid): void
    {
        $dir=$this->brandAssetDirectory();$patterns=match($slot){'logo'=>['logo.*'],'logo_dark'=>['logo-dark.*'],'mark'=>['mark.*','favicon-32.png','apple-touch-icon.png','pwa-192.png','pwa-512.png'],'favicon'=>['favicon.*'],default=>[]};foreach($patterns as$pattern)foreach(glob($dir.'/'.$pattern)?:[] as$f)if(is_file($f))@unlink($f);TenantData::setSetting($setting,'',$userGuid);if($slot==='mark'){$favicon=(string)TenantData::setting('brand.favicon_path','');foreach(['brand.apple_touch_icon_path','brand.pwa_icon_192_path','brand.pwa_icon_512_path'] as$key)TenantData::setSetting($key,'',$userGuid);if(str_contains($favicon,'/favicon-32.png'))TenantData::setSetting('brand.favicon_path','',$userGuid);}
    }

    private function adminSettings(string $method): never
    {
        if($method==='POST'){$u=Auth::user();foreach(SettingsCatalog::keys() as$key){$raw=$this->postedSetting($key,null,$present);if(!$present)continue;TenantData::setSetting($key,trim((string)$raw),$u['user_guid']??null);}Audit::log('settings.legacy.updated','settings',RequestContext::tenantGuid());Http::redirect('/admin/settings/appearance?saved=1');}Http::redirect('/admin/settings/appearance');
    }

