            'processing.thumbnail_width'=>[120,1200],
            'processing.highres_quality'=>[55,100],
            'processing.preview_quality'=>[55,100],
            'processing.thumbnail_quality'=>[45,100],
            'processing.tile_quality'=>[45,100],
            'processing.ocr_timeout_seconds'=>[30,900],
            'processing.recovery_max_rescues'=>[0,2],
            'processing.recovery_dpi_ceiling'=>[120,220],
            'processing.recovery_ocr_timeout_seconds'=>[120,900],
