            Http::redirect('/admin/settings/processing?saved=1');
        }
        $tabs='';foreach(SettingsCatalog::groups() as$key=>$g)$tabs.='<a class="settings-tab '.($key==='processing'?'active':'').'" href="/admin/settings/'.$this->e($key).'">'.$this->e($g['label']).'</a>';
        $v=[];foreach($cfg['fields'] as$key=>$field)$v[$key]=(string)TenantData::setting($key,$field[2]);
        $num=function(string$key,string$label,int$min,int$max,string$hint='')use(&$v){return'<label>'.$this->e($label).'<input type="number" name="settings['.$this->e($key).']" min="'.$min.'" max="'.$max.'" value="'.$this->e($v[$key]??'').'">'.($hint!==''?'<small>'.$this->e($hint).'</small>':'').'</label>';};
        $sel=function(string$key,string$label,array$options,string$hint='')use(&$v){$o='<label>'.$this->e($label).'<select name="settings['.$this->e($key).']">';foreach($options as$value=>$text){if(is_int($value))$value=(string)$text;$o.='<option value="'.$this->e((string)$value).'"'.(($v[$key]??'')===(string)$value?' selected':'').'>'.$this->e((string)$text).'</option>';}$o.='</select>'.($hint!==''?'<small>'.$this->e($hint).'</small>':'').'</label>';return$o;};
        $tileOptions='';foreach($allowedTiles as$tile)$tileOptions.='<option value="'.$tile.'"'.(($v['processing.tile_size']??'')===$tile?' selected':'').'>'.$tile.' px</option>';
        $recoveryTiles='';foreach($allowedRecoveryTiles as$tile)$recoveryTiles.='<option value="'.$tile.'"'.(($v['processing.recovery_tile_size']??'')===$tile?' selected':'').'>'.$tile.' px</option>';
        $autoRescue=($v['processing.recovery_auto_rescue']??'off')==='on';
        $h='<section class="admin-head processing-settings-head"><div><span class="eyebrow">PUBLISHER CONTROL</span><h1>Processing</h1><p class="muted">Configure default media generation, OCR and safe recovery behavior. One-off Reprocess overrides never mutate these publisher defaults.</p></div><span class="pill">Global default</span></section><nav class="settings-tabs">'.$tabs.'</nav>'.(!empty($_GET['saved'])?'<div class="alert success">Processing settings saved. New processing runs will use the updated defaults.</div>':'');
        $h.='<form method="post" class="processing-settings-form" data-processing-settings>'.$this->csrf();
        $h.='<section class="processing-preset-bar"><div><span class="eyebrow">SAFE PRESETS</span><strong>Start from a tested processing profile</strong><small>Presets only change fields in this form. Nothing is saved until you click Save Processing.</small></div><div class="processing-preset-actions"><button type="button" class="btn ghost" data-processing-preset="recommended">Recommended</button><button type="button" class="btn ghost" data-processing-preset="quality">High fidelity</button><button type="button" class="btn ghost" data-processing-preset="recovery">Low-memory recovery</button></div><span class="processing-preset-state" data-processing-preset-state hidden>Unsaved preset</span></section>';
        $h.='<section class="panel processing-settings-card"><div class="section-head"><div><span class="eyebrow">PDF PROCESSING</span><h2>Source rendering</h2><p class="muted">Defaults used by new editions unless a Reprocess run supplies a one-off override.</p></div><span class="pill">WebP master</span></div><div class="processing-settings-grid"><div class="fixed-setting"><strong>WebP — recommended</strong><span>Reader-delivery master format. Temporary renderer JPEGs remain private processing sources.</span></div>'.$num('processing.pdf_dpi','PDF render DPI',96,400,'180 DPI is the balanced production default.').$num('processing.highres_quality','High-resolution WebP quality',55,100,'Controls the reader master asset; higher values increase storage and encode time.').'</div></section>';
        $h.='<section class="panel processing-settings-card"><div class="section-head"><div><span class="eyebrow">GENERATED ASSETS</span><h2>Reader media</h2><p class="muted">Output dimensions and WebP quality for fast browsing and Deep Zoom.</p></div><span class="pill">Media generation</span></div><div class="processing-settings-grid">'.$num('processing.preview_width','Preview width',640,3000).$num('processing.thumbnail_width','Thumbnail width',120,1200).'<label>Deep Zoom tile size<select name="settings[processing.tile_size]">'.$tileOptions.'</select><small>512 px is the normal balance; 384 px reduces recovery memory pressure.</small></label>'.$num('processing.preview_quality','Preview WebP quality',55,100).$num('processing.thumbnail_quality','Thumbnail WebP quality',45,100).$num('processing.tile_quality','Deep Zoom WebP quality',45,100).'</div></section>';
        $h.='<section class="panel processing-settings-card"><div class="section-head"><div><span class="eyebrow">OCR</span><h2>Text extraction</h2><p class="muted">Language detection and the per-page processing deadline used by Tesseract.</p></div><span class="pill">Search & article layer</span></div><div class="processing-settings-grid"><label>OCR languages / auto profile<input name="settings[processing.ocr_languages]" value="'.$this->e($v['processing.ocr_languages']??'auto').'" placeholder="auto or mar+eng"><small>Use auto to derive the profile from edition language when enabled.</small></label>'.$num('processing.ocr_timeout_seconds','OCR timeout / page (seconds)',30,900).$sel('processing.auto_language','Use edition language OCR profile',['on'=>'On','off'=>'Off']).'</div></section>';
                $h.='<details class="panel processing-fallback-card"><summary><div><span class="eyebrow">PROCESSING FALLBACK</span><strong>Runtime retry & renderer safeguards</strong><small>Infrastructure recovery options that most publishers rarely need to change.</small></div><span class="pill warning">Advanced</span></summary><div class="processing-fallback-grid"><div><strong>Renderer chain</strong><span>pdftoppm first · Imagick fallback when available</span></div><div><strong>Normal queue retries</strong><span>Render '.QueueService::maxAttempts('EDITION_RENDER').' · Assets '.QueueService::maxAttempts('PAGE_ASSETS').' · OCR '.QueueService::maxAttempts('PAGE_OCR').' · Finalize '.QueueService::maxAttempts('EDITION_FINALIZE').'</span></div><div><strong>Transport</strong><span>RabbitMQ + Supervisor remains managed under Infrastructure.</span></div><a class="btn ghost" href="/admin/system/infrastructure">Open Infrastructure</a></div></details>';
$h.='<section class="panel processing-settings-card processing-recovery-card"><div class="section-head"><div><span class="eyebrow">RECOVERY & REPROCESSING</span><h2>Safe failure recovery</h2><p class="muted">Normal RabbitMQ retries run first. Optional automatic rescue starts one new full processing pipeline only after those retries are exhausted.</p></div><span class="status '.($autoRescue?'ready':'draft').'">'.($autoRescue?'AUTO RESCUE ON':'MANUAL RECOVERY').'</span></div><div class="processing-recovery-summary"><div><strong>Previous attempts are always retained</strong><span>Recovery creates a new pipeline and keeps the failed attempt available in Processing History.</span></div><div><strong>Published editions stay protected</strong><span>Direct live reprocessing remains blocked until staged asset build + atomic swap is implemented.</span></div></div><div class="processing-settings-grid">'.$sel('processing.recovery_manual_smart','Preselect smart corrections in manual Reprocess',['on'=>'On — recommended','off'=>'Off — exact defaults']).$sel('processing.recovery_auto_rescue','Automatic rescue after normal retries',['off'=>'Off — manual approval','on'=>'On — one bounded recovery pipeline']).$num('processing.recovery_max_rescues','Maximum automatic rescue passes',0,2,'Recommended: 1. Zero disables automatic rescue even if the switch is on.').$num('processing.recovery_dpi_ceiling','Recovery DPI ceiling',120,220,'Smart recovery will not raster above this DPI for geometry/memory failures.').'<label>Recovery Deep Zoom tile size<select name="settings[processing.recovery_tile_size]">'.$recoveryTiles.'</select><small>Used by the error-aware recovery profile when tile/render failures are detected.</small></label>'.$num('processing.recovery_ocr_timeout_seconds','Recovery OCR timeout / page',120,900,'Used when OCR or timeout signatures are detected.').'</div><details class="processing-advanced"><summary>Advanced recovery behavior</summary><div><p>Automatic rescue is deliberately bounded. It runs only for unpublished editions, only after normal job retries are exhausted, and only for recoverable signatures such as geometry, image write, renderer, memory, OCR or timeout failures.</p><p>OCR-only page failures do not block publication; the edition may become READY with OCR warnings. Asset failures remain publication-blocking.</p></div></details></section>';
        $h.='<div class="processing-settings-save"><div><strong>Publisher processing defaults</strong><span>Changes apply to future processing runs. Existing completed edition assets are not rewritten.</span></div><button class="btn primary">Save Processing</button></div></form>';
